import { Decoration, ViewPlugin } from "@codemirror/view";
import { syntaxTree } from "@codemirror/language";

const taskListPattern = /^(\s*)([-*+])\s+\[([ xX])\](\s+)/;

function addLineClasses(lineClassMap, lineFrom, classNames) {
  if (!classNames.length) {
    return;
  }

  let classSet = lineClassMap.get(lineFrom);
  if (!classSet) {
    classSet = new Set();
    lineClassMap.set(lineFrom, classSet);
  }

  for (const className of classNames) {
    classSet.add(className);
  }
}

function getHeadingLineClasses(nodeName) {
  const level = Number(nodeName.slice("ATXHeading".length));
  if (!Number.isInteger(level) || level < 1 || level > 4) {
    return [];
  }

  return ["cm-markdoc-headingLine", `cm-markdoc-headingLine--h${level}`];
}

function getListLineClasses(node, lineText) {
  const classes = [];

  if (node.matchContext(["BulletList", "ListItem"])) {
    classes.push("cm-markdoc-listLine", "cm-markdoc-listLine--bullet");
  }

  if (node.matchContext(["OrderedList", "ListItem"])) {
    classes.push("cm-markdoc-listLine", "cm-markdoc-listLine--ordered");
  }

  if (!classes.length) {
    return classes;
  }

  if (/^\s+/.test(lineText)) {
    classes.push("cm-markdoc-listLine--nested");
  }

  if (taskListPattern.test(lineText)) {
    classes.push("cm-markdoc-listLine--task");
  }

  return classes;
}

function buildDecorations(view) {
  const lineClassMap = new Map();

  for (const { from, to } of view.visibleRanges) {
    syntaxTree(view.state).iterate({
      from,
      to,
      enter(node) {
        if (node.name.startsWith("ATXHeading")) {
          const line = view.state.doc.lineAt(node.from);
          addLineClasses(lineClassMap, line.from, getHeadingLineClasses(node.name));
        }

        if (node.name === "ListMark") {
          const line = view.state.doc.lineAt(node.from);
          addLineClasses(lineClassMap, line.from, getListLineClasses(node, line.text));
        }

        return undefined;
      },
    });
  }

  const decorations = [];
  for (const [lineFrom, classSet] of lineClassMap) {
    decorations.push(Decoration.line({ class: Array.from(classSet).join(" ") }).range(lineFrom));
  }

  return Decoration.set(decorations, true);
}

export default ViewPlugin.fromClass(class {
  constructor(view) {
    this.decorations = buildDecorations(view);
  }

  update(update) {
    if (update.docChanged || update.viewportChanged) {
      this.decorations = buildDecorations(update.view);
    }
  }
}, {
  decorations: (instance) => instance.decorations,
});
