import { RangeSet, StateEffect, StateField } from "@codemirror/state";
import { Decoration, EditorView, WidgetType } from "@codemirror/view";
import {
  extractMarkdownMetadata,
  formatMarkdownMetadataSummary,
  getMarkdownMetadataRanges,
} from "./metadata.js";

export const setMetadataCollapsedEffect = StateEffect.define();

const metadataCollapsedField = StateField.define({
  create() {
    return true;
  },

  update(value, transaction) {
    for (const effect of transaction.effects) {
      if (effect.is(setMetadataCollapsedEffect)) {
        return Boolean(effect.value);
      }
    }

    return value;
  },
});

function dispatchMetadataCollapsed(view, nextValue, onCollapsedChange) {
  view.dispatch({
    effects: setMetadataCollapsedEffect.of(nextValue),
  });
  onCollapsedChange?.(nextValue);
  view.focus();
}

class MetadataToggleWidget extends WidgetType {
  constructor({ collapsed, summary, onCollapsedChange }) {
    super();
    this.collapsed = collapsed;
    this.summary = summary;
    this.onCollapsedChange = onCollapsedChange;
  }

  eq(other) {
    return (
      other.collapsed === this.collapsed
      && other.summary === this.summary
    );
  }

  toDOM(view) {
    const wrap = document.createElement("div");
    wrap.className = this.collapsed ? "cm-metadata-summaryWidget" : "cm-metadata-headerWidget";
    wrap.setAttribute("contenteditable", "false");

    const button = wrap.appendChild(document.createElement("button"));
    button.type = "button";
    button.className = [
      "markdown-engine-metadataToggleButton",
      this.collapsed ? "is-collapsed" : "is-expanded",
    ].join(" ");
    button.setAttribute("aria-expanded", String(!this.collapsed));
    button.title = this.collapsed ? "Mostrar propiedades" : "Ocultar propiedades";

    const main = button.appendChild(document.createElement("span"));
    main.className = "markdown-engine-metadataToggleMain";

    const disclosure = main.appendChild(document.createElement("span"));
    disclosure.className = "markdown-engine-metadataDisclosure";
    disclosure.setAttribute("aria-hidden", "true");

    const label = main.appendChild(document.createElement("span"));
    label.className = "markdown-engine-metadataLabel";
    label.textContent = "Propiedades";

    if (this.summary) {
      const summary = button.appendChild(document.createElement("span"));
      summary.className = "markdown-engine-metadataSummary";
      summary.textContent = this.summary;
    }

    button.addEventListener("mousedown", (event) => {
      event.preventDefault();
      event.stopPropagation();
    });

    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      dispatchMetadataCollapsed(view, !this.collapsed, this.onCollapsedChange);
    });

    return wrap;
  }

  ignoreEvent() {
    return true;
  }
}

function buildMetadataDecorations(state, collapsed, onCollapsedChange) {
  const source = state.doc.toString();
  const ranges = getMarkdownMetadataRanges(source);
  if (!ranges.length) {
    return RangeSet.empty;
  }

  const { metadata } = extractMarkdownMetadata(source);
  const summary = formatMarkdownMetadataSummary(metadata.length);

  if (collapsed) {
    return RangeSet.of([
      Decoration.replace({
        widget: new MetadataToggleWidget({
          collapsed: true,
          summary,
          onCollapsedChange,
        }),
        block: true,
      }).range(ranges[0].from, ranges[ranges.length - 1].to),
    ], true);
  }

  const decorations = [
    Decoration.widget({
      widget: new MetadataToggleWidget({
        collapsed: false,
        summary,
        onCollapsedChange,
      }),
      block: true,
      side: -1,
    }).range(ranges[0].from),
  ];

  for (const range of ranges) {
    decorations.push(
      Decoration.line({
        class: [
          "cm-metadata-line",
          range.kind === "delimiter" ? "cm-metadata-line-delimiter" : "",
          range.isFirst ? "cm-metadata-line-first" : "",
          range.isLast ? "cm-metadata-line-last" : "",
        ].filter(Boolean).join(" "),
      }).range(range.from),
    );

    if (range.keyFrom != null && range.keyTo != null) {
      decorations.push(Decoration.mark({ class: "cm-metadata-key" }).range(range.keyFrom, range.keyTo));
    }

    if (range.separatorFrom != null && range.separatorTo != null) {
      decorations.push(Decoration.mark({ class: "cm-metadata-separator" }).range(range.separatorFrom, range.separatorTo));
    }

    if (range.valueFrom != null && range.valueTo != null) {
      decorations.push(Decoration.mark({ class: "cm-metadata-value" }).range(range.valueFrom, range.valueTo));
    }
  }

  return RangeSet.of(decorations, true);
}

export default function metadataLiveDecorations({
  defaultCollapsed = true,
  onCollapsedChange = null,
} = {}) {
  const initialCollapsed = Boolean(defaultCollapsed);

  const metadataDecorationsField = StateField.define({
    create(state) {
      const collapsed = state.field(metadataCollapsedField, false) ?? initialCollapsed;
      return buildMetadataDecorations(state, collapsed, onCollapsedChange);
    },

    update(decorations, transaction) {
      const collapsedChanged = transaction.effects.some((effect) => effect.is(setMetadataCollapsedEffect));
      if (!transaction.docChanged && !collapsedChanged) {
        return decorations;
      }

      const collapsed = transaction.state.field(metadataCollapsedField, false) ?? initialCollapsed;
      return buildMetadataDecorations(transaction.state, collapsed, onCollapsedChange);
    },

    provide(field) {
      return EditorView.decorations.from(field);
    },
  });

  return [
    metadataCollapsedField.init(() => initialCollapsed),
    metadataDecorationsField,
  ];
}
