import { RangeSet, StateField } from "@codemirror/state";
import { syntaxTree } from "@codemirror/language";
import { Decoration, EditorView } from "@codemirror/view";

const inlineCodeDecoration = Decoration.mark({ class: "cm-markdown-inlineCode" });

function getInlineCodeContentRange(state, node) {
  const raw = state.doc.sliceString(node.from, node.to);
  const opening = raw.match(/^`+/)?.[0]?.length ?? 0;
  const closing = raw.match(/`+$/)?.[0]?.length ?? 0;

  if (!opening || opening !== closing) {
    return null;
  }

  const from = node.from + opening;
  const to = node.to - closing;
  return from < to ? { from, to } : null;
}

function buildDecorations(state) {
  const decorations = [];

  syntaxTree(state).iterate({
    enter(node) {
      if (node.name !== "InlineCode") {
        return undefined;
      }

      const range = getInlineCodeContentRange(state, node);
      if (range) {
        decorations.push(inlineCodeDecoration.range(range.from, range.to));
      }

      return undefined;
    },
  });

  return RangeSet.of(decorations, true);
}

export default StateField.define({
  create(state) {
    return buildDecorations(state);
  },

  update(_decorations, transaction) {
    return buildDecorations(transaction.state);
  },

  provide(field) {
    return EditorView.decorations.from(field);
  },
});
