import { Decoration, EditorView, WidgetType } from "@codemirror/view";
import { RangeSet, StateField } from "@codemirror/state";
import { syntaxTree } from "@codemirror/language";
import { getMarkdownMetadataRanges } from "./metadata.js";
import { getBlockRenderDefinition } from "./blockRenderRegistry.js";

const patternTag = /{%\s*(?<closing>\/)?(?<tag>[a-zA-Z0-9-_]+)(?<attrs>\s+[^]+)?\s*(?<self>\/)?%}\s*$/m;
const calloutHeaderPattern = /^\s*>\s+\[!([A-Za-z]+)\]/;

const ACTIVE_BLOCK_PRIORITY = {
  blockquote: 1,
  callout: 2,
};

class RenderBlockWidget extends WidgetType {
  constructor({ source, rendered, kind, lineOffset }) {
    super();
    this.source = source;
    this.rendered = rendered;
    this.kind = kind;
    this.lineOffset = lineOffset;
  }

  eq(widget) {
    return widget.source === this.source && widget.rendered === this.rendered && widget.kind === this.kind;
  }

  updateDOM(dom) {
    if (!(dom instanceof HTMLElement)) {
      return false;
    }

    if (dom.dataset.blockKind !== this.kind) {
      return false;
    }

    dom.innerHTML = this.rendered;
    dom.setAttribute("data-block-kind", this.kind);
    applyAbsoluteTaskLineOffsets(dom, this.lineOffset);
    return true;
  }

  toDOM() {
    const content = document.createElement("div");
    content.setAttribute("contenteditable", "false");
    content.className = "cm-markdoc-renderBlock markdown-engine-liveWidget";
    content.setAttribute("data-block-kind", this.kind);
    content.innerHTML = this.rendered;
    applyAbsoluteTaskLineOffsets(content, this.lineOffset);
    return content;
  }

  ignoreEvent() {
    return false;
  }
}

function applyAbsoluteTaskLineOffsets(root, lineOffset) {
  root.querySelectorAll(".markdown-task-checkboxInput").forEach((input) => {
    const relativeLine = Number(input.dataset.sourceLine);
    if (!Number.isFinite(relativeLine) || relativeLine < 0) {
      return;
    }

    input.dataset.sourceLine = String(lineOffset + relativeLine);
  });
}

function getMetadataBoundary(state) {
  const ranges = getMarkdownMetadataRanges(state.doc.toString());
  if (!ranges.length) {
    return -1;
  }

  return ranges[ranges.length - 1].to;
}

function shouldAbsorbLeadingBlankLines(kind) {
  return [
    "heading-2",
    "heading-3",
    "heading-4",
    "paragraph",
    "bullet-list",
    "ordered-list",
    "table",
    "code-fence",
    "horizontal-rule",
  ].includes(kind);
}

function expandBlockStartToLeadingBlankLines(state, from, metadataBoundary, kind) {
  if (!shouldAbsorbLeadingBlankLines(kind)) {
    return from;
  }

  let currentFrom = from;
  let line = state.doc.lineAt(currentFrom);

  while (line.number > 1) {
    const previousLine = state.doc.line(line.number - 1);
    if (previousLine.to <= metadataBoundary || previousLine.text.trim()) {
      break;
    }

    currentFrom = previousLine.from;
    line = previousLine;
  }

  return currentFrom;
}

function createBlockDecoration(state, from, to, definition, config) {
  const metadataBoundary = getMetadataBoundary(state);
  const effectiveFrom = expandBlockStartToLeadingBlankLines(state, from, metadataBoundary, definition.kind);
  const source = state.doc.sliceString(effectiveFrom, to);
  const rendered = definition.render(source, config);

  return Decoration.replace({
    widget: new RenderBlockWidget({
      source,
      rendered,
      kind: definition.kind,
      lineOffset: state.doc.lineAt(effectiveFrom).number - 1,
    }),
    block: true,
  }).range(effectiveFrom, to);
}

function clampResolvedPosition(state, position) {
  if (state.doc.length <= 0) {
    return 0;
  }

  return Math.max(0, Math.min(position, state.doc.length - 1));
}

function selectionIsWithinNode(selection, node) {
  return selection.from >= node.from && selection.to <= node.to;
}

function cursorTouchesNode(position, node) {
  return position >= node.from && position <= node.to;
}

function resolveBlockKindFromNodeName(nodeName) {
  switch (nodeName) {
    case "Blockquote":
      return "blockquote";
    default:
      return null;
  }
}

function resolveBlockquoteKind(state, node) {
  const startLine = state.doc.lineAt(node.from).number;
  const endLine = state.doc.lineAt(Math.max(node.from, node.to - 1)).number;

  for (let lineNumber = startLine; lineNumber <= endLine; lineNumber += 1) {
    const line = state.doc.line(lineNumber);
    if (!line.text.trim()) {
      continue;
    }

    const calloutMatch = line.text.match(calloutHeaderPattern);
    if (!calloutMatch) {
      return {
        kind: "blockquote",
        variant: "",
      };
    }

    return {
      kind: "callout",
      variant: String(calloutMatch[1] || "").toLowerCase(),
    };
  }

  return {
    kind: "blockquote",
    variant: "",
  };
}

function resolveActiveBlockContext(state) {
  const selection = state.selection.main;
  let bestContext = null;
  let bestPriority = -1;
  const tree = syntaxTree(state);

  const considerNodePath = (startNode, predicate) => {
    let node = startNode;

    while (node) {
      if (predicate(node)) {
        const resolvedKind = resolveBlockKindFromNodeName(node.name);
        if (resolvedKind) {
          const context =
            resolvedKind === "blockquote"
              ? {
                ...resolveBlockquoteKind(state, node),
                from: node.from,
                to: node.to,
              }
              : {
                kind: resolvedKind,
                variant: "",
                from: node.from,
                to: node.to,
              };
          const priority = ACTIVE_BLOCK_PRIORITY[context.kind] ?? 0;

          if (priority >= bestPriority) {
            bestContext = context;
            bestPriority = priority;
          }
        }
      }

      node = node.parent;
    }
  };

  if (selection.empty) {
    const position = clampResolvedPosition(state, selection.from);
    const sides = [selection.assoc || 1, 1, -1, 0];
    const seenRoots = new Set();

    for (const side of sides) {
      const rootNode = tree.resolveInner(position, side);
      const rootKey = `${rootNode.name}:${rootNode.from}:${rootNode.to}`;
      if (seenRoots.has(rootKey)) {
        continue;
      }

      seenRoots.add(rootKey);
      considerNodePath(rootNode, (node) => cursorTouchesNode(position, node));
    }

    return bestContext;
  }

  const fromPosition = clampResolvedPosition(state, selection.from);
  const toPosition = clampResolvedPosition(state, selection.to);
  const toNode = tree.resolveInner(toPosition, -1);
  const fromNode = tree.resolveInner(fromPosition, 1);

  considerNodePath(
    fromNode,
    (node) => selectionIsWithinNode(selection, node) && toNode.from >= node.from && toNode.to <= node.to,
  );

  return bestContext;
}

function createLineDecoration(line, className, styleText = "") {
  const attributes = {
    class: className,
  };

  if (styleText) {
    attributes.style = styleText;
  }

  return Decoration.line({ attributes }).range(line.from);
}

function collectActiveBlockDecorations(state) {
  const context = resolveActiveBlockContext(state);
  if (!context) {
    return [];
  }

  const decorations = [];
  const startLine = state.doc.lineAt(context.from).number;
  const endLine = state.doc.lineAt(Math.max(context.from, context.to - 1)).number;

  for (let lineNumber = startLine; lineNumber <= endLine; lineNumber += 1) {
    const line = state.doc.line(lineNumber);
    if (context.kind === "blockquote") {
      if (!line.text.trim()) {
        continue;
      }

      decorations.push(createLineDecoration(line, "cm-markdoc-activeBlockLine cm-quote-line"));
      continue;
    }

    if (context.kind === "callout") {
      if (!line.text.trim()) {
        continue;
      }

      const variantClass = context.variant ? ` cm-callout-line-${context.variant}` : "";
      decorations.push(
        createLineDecoration(line, `cm-markdoc-activeBlockLine cm-callout-line${variantClass}`),
      );
    }
  }

  return decorations;
}

function replaceBlocks(state, config, from, to) {
  const decorations = [];
  const [cursor] = state.selection.ranges;
  const metadataBoundary = getMetadataBoundary(state);
  const tags = [];
  const stack = [];

  syntaxTree(state).iterate({
    from,
    to,
    enter(node) {
      if (metadataBoundary >= 0 && node.to <= metadataBoundary) {
        return false;
      }

      if (node.name === "MarkdocTag") {
        const text = state.doc.sliceString(node.from, node.to);
        const match = text.match(patternTag);

        if (match?.groups?.self) {
          tags.push([node.from, node.to]);
          return undefined;
        }

        if (match?.groups?.closing) {
          const last = stack.pop();
          if (last != null) {
            tags.push([last, node.to]);
          }
          return undefined;
        }

        stack.push(node.from);
        return undefined;
      }

      const definition = getBlockRenderDefinition(node.name);
      if (!definition) {
        return undefined;
      }

      if (cursor.from >= node.from && cursor.to <= node.to) {
        return false;
      }

      decorations.push(createBlockDecoration(state, node.from, node.to, definition, config));
      return false;
    },
  });

  const markdocDefinition = getBlockRenderDefinition("MarkdocTag");
  for (const [fromPosition, toPosition] of tags) {
    if (!markdocDefinition) {
      break;
    }

    if (metadataBoundary >= 0 && toPosition <= metadataBoundary) {
      continue;
    }

    if (cursor.from >= fromPosition && cursor.to <= toPosition) {
      continue;
    }

    decorations.push(createBlockDecoration(state, fromPosition, toPosition, markdocDefinition, config));
  }

  return decorations;
}

export default function renderBlock(config) {
  return StateField.define({
    create(state) {
      return RangeSet.of([...replaceBlocks(state, config), ...collectActiveBlockDecorations(state)], true);
    },

    update(_decorations, transaction) {
      return RangeSet.of(
        [...replaceBlocks(transaction.state, config), ...collectActiveBlockDecorations(transaction.state)],
        true,
      );
    },

    provide(field) {
      return EditorView.decorations.from(field);
    },
  });
}
