import { ViewPlugin } from "@codemirror/view";
import { syntaxHighlighting } from "@codemirror/language";
import { markdown, markdownLanguage } from "@codemirror/lang-markdown";
import tagParser from "./tagParser.js";
import highlightStyle from "./highlightStyle.js";
import RichEditPlugin from "./syntaxCleaner.js";
import renderBlock from "./renderedBlockWidgets.js";
import metadataLiveDecorations from "./metadataLiveDecorations.js";
import liveLinkDecorations from "./liveLinkDecorations.js";
import taskCheckboxPlugin from "./taskCheckboxPlugin.js";
import highlightDecorations from "./highlightDecorations.js";
import inlineCodeDecorations from "./inlineCodeDecorations.js";
import structuralLineDecorations from "./structuralLineDecorations.js";
import inlineHtmlDecorations from "./inlineHtmlDecorations.js";

const EXTERNAL_TARGET_PATTERN = /^[a-z][a-z0-9+.-]*:/i;

function normalizeWikiLinkTarget(value) {
  const raw = String(value || "").trim();
  if (!raw || raw.includes("|")) {
    return null;
  }

  return raw;
}

function isInternalTarget(target) {
  const normalized = String(target || "").trim();
  if (!normalized) {
    return false;
  }

  return !EXTERNAL_TARGET_PATTERN.test(normalized) && !normalized.startsWith("#");
}

function getElementTarget(target) {
  if (target instanceof Element) {
    return target;
  }

  return target?.parentElement instanceof Element ? target.parentElement : null;
}

function resolveRenderedHtmlLink(target) {
  const element = getElementTarget(target);
  const anchor =
    element?.closest(".cm-markdoc-renderBlock a, .cm-markdoc-renderInlineHtml a") || null;
  if (!anchor) {
    return null;
  }

  const wikiTarget = anchor.dataset.nexusWikilink;
  const href = anchor.getAttribute("href");
  const resolvedTarget = wikiTarget || href;
  if (!resolvedTarget || !isInternalTarget(resolvedTarget)) {
    return null;
  }

  return {
    target: resolvedTarget,
    isWikiLink: Boolean(wikiTarget),
  };
}

const taskLinePattern = /^(\s*[-*+]\s+)\[([ xX])\](\s+)/;

function toggleRenderedBlockTaskCheckbox(view, target) {
  const element = getElementTarget(target);
  const widget = element?.closest(".markdown-task-checkbox") || null;
  if (!(widget instanceof HTMLElement)) {
    return false;
  }

  const input = widget.querySelector(".markdown-task-checkboxInput");
  if (!(input instanceof HTMLInputElement)) {
    return false;
  }

  const sourceLine = Number(input.dataset.sourceLine);
  if (!Number.isFinite(sourceLine) || sourceLine < 0) {
    return false;
  }

  const line = view.state.doc.line(sourceLine + 1);
  const match = line.text.match(taskLinePattern);
  if (!match) {
    return false;
  }

  const markerFrom = line.from + match[1].length;
  view.dispatch({
    changes: {
      from: markerFrom,
      to: markerFrom + 3,
      insert: input.checked ? "[ ]" : "[x]",
    },
  });

  return true;
}

function resolveWikiLinkAtPosition(state, position) {
  const line = state.doc.lineAt(position);
  const pattern = /\[\[([^\]\r\n]+)\]\]/g;
  let match = pattern.exec(line.text);

  while (match) {
    const from = line.from + match.index;
    const to = from + match[0].length;

    if (position >= from && position < to) {
      const target = normalizeWikiLinkTarget(match[1]);
      if (target) {
        return {
          target,
          isWikiLink: true,
        };
      }
    }

    match = pattern.exec(line.text);
  }

  return null;
}

function extractTargetFromMarkdownDestination(rawDestination) {
  const trimmed = String(rawDestination || "").trim();
  if (!trimmed) {
    return "";
  }

  if (trimmed.startsWith("<") && trimmed.endsWith(">")) {
    return trimmed.slice(1, -1).trim();
  }

  const titledDestinationMatch = trimmed.match(/^(.*?)(\s+["'][^"']*["'])$/);
  return titledDestinationMatch ? titledDestinationMatch[1].trim() : trimmed;
}

function collectMarkdownLinksFromLine(line) {
  const links = [];
  const text = line.text;

  function findLabelEnd(startIndex) {
    for (let index = startIndex + 1; index < text.length; index += 1) {
      const character = text[index];
      if (character === "\n" || character === "\r") {
        return -1;
      }
      if (character === "]" && text[index - 1] !== "\\") {
        return index;
      }
    }
    return -1;
  }

  function findDestinationEnd(openParenIndex) {
    let depth = 1;

    for (let index = openParenIndex + 1; index < text.length; index += 1) {
      const character = text[index];

      if (character === "\n" || character === "\r") {
        return -1;
      }

      if (character === "\\" && index + 1 < text.length) {
        index += 1;
        continue;
      }

      if (character === "(") {
        depth += 1;
        continue;
      }

      if (character === ")") {
        depth -= 1;
        if (depth === 0) {
          return index;
        }
      }
    }

    return -1;
  }

  for (let index = 0; index < text.length; index += 1) {
    if (text[index] !== "[" || text[index - 1] === "!") {
      continue;
    }

    const labelEnd = findLabelEnd(index);
    if (labelEnd < 0 || text[labelEnd + 1] !== "(") {
      continue;
    }

    const destinationEnd = findDestinationEnd(labelEnd + 1);
    if (destinationEnd < 0) {
      continue;
    }

    const target = extractTargetFromMarkdownDestination(text.slice(labelEnd + 2, destinationEnd));
    if (target && isInternalTarget(target)) {
      links.push({
        target,
        from: line.from + index,
        to: line.from + destinationEnd + 1,
        labelFrom: line.from + index + 1,
        labelTo: line.from + labelEnd,
      });
    }

    index = destinationEnd;
  }

  return links;
}

function resolveMarkdownLinkAtPosition(state, position) {
  const line = state.doc.lineAt(position);
  for (const link of collectMarkdownLinksFromLine(line)) {
    if (position >= link.from && position < link.to) {
      return {
        target: link.target,
        isWikiLink: false,
      };
    }
  }

  return null;
}

function resolveInlineLinkInfoAtPosition(state, position) {
  const line = state.doc.lineAt(position);
  const wikiPattern = /\[\[([^\]\r\n]+)\]\]/g;
  let match = wikiPattern.exec(line.text);
  while (match) {
    const from = line.from + match.index;
    const to = from + match[0].length;
    const target = normalizeWikiLinkTarget(match[1]);

    if (target && isInternalTarget(target) && position >= from && position < to) {
      return {
        target,
        isWikiLink: true,
        from,
        to,
        labelFrom: from + 2,
        labelTo: to - 2,
      };
    }

    match = wikiPattern.exec(line.text);
  }

  for (const link of collectMarkdownLinksFromLine(line)) {
    if (position >= link.from && position < link.to) {
      return {
        target: link.target,
        isWikiLink: false,
        from: link.from,
        to: link.to,
        labelFrom: link.labelFrom,
        labelTo: link.labelTo,
      };
    }
  }

  return null;
}

function getLinkVisibleRect(view, linkInfo) {
  const rects = [];

  for (let position = linkInfo.labelFrom; position < linkInfo.labelTo; position += 1) {
    const rect = view.coordsForChar(position);
    if (rect) {
      rects.push(rect);
    }
  }

  if (!rects.length) {
    return null;
  }

  return {
    left: Math.min(...rects.map((rect) => rect.left)),
    right: Math.max(...rects.map((rect) => rect.right)),
    top: Math.min(...rects.map((rect) => rect.top)),
    bottom: Math.max(...rects.map((rect) => rect.bottom)),
  };
}

function pointIsInsideRect(x, y, rect) {
  return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
}

function resolveDecoratedInlineLink(view, event) {
  const ownerDocument = view.dom.ownerDocument;
  if (typeof ownerDocument?.elementsFromPoint !== "function") {
    return null;
  }

  const candidates = ownerDocument.elementsFromPoint(event.clientX, event.clientY);
  const seen = new Set();

  for (const candidate of candidates) {
    if (!(candidate instanceof Element)) {
      continue;
    }

    const linkElement = candidate.closest(".cm-markdown-liveLink");
    if (!linkElement || seen.has(linkElement)) {
      continue;
    }
    seen.add(linkElement);

    let position = null;
    try {
      position = view.posAtDOM(linkElement);
    } catch {
      position = null;
    }

    if (position == null) {
      continue;
    }

    const linkInfo = resolveInlineLinkInfoAtPosition(view.state, position);
    if (!linkInfo) {
      continue;
    }

    const visibleRect = getLinkVisibleRect(view, linkInfo);
    if (!visibleRect || !pointIsInsideRect(event.clientX, event.clientY, visibleRect)) {
      continue;
    }

    return {
      target: linkInfo.target,
      isWikiLink: linkInfo.isWikiLink,
    };
  }

  return null;
}

function resolveEditorLink(view, event) {
  const renderedHtmlLink = resolveRenderedHtmlLink(event.target);
  if (renderedHtmlLink) {
    return renderedHtmlLink;
  }

  return resolveDecoratedInlineLink(view, event);
}

function focusInlineHtmlSource(view, target) {
  const element = getElementTarget(target);
  if (!element) {
    return false;
  }

  if (element.closest(".cm-markdoc-renderInlineHtml a")) {
    return false;
  }

  const widget = element.closest(".cm-markdoc-renderInlineHtml");
  if (!(widget instanceof HTMLElement)) {
    return false;
  }

  const from = Number(widget.dataset.sourceFrom);
  const to = Number(widget.dataset.sourceTo);
  if (!Number.isFinite(from) || !Number.isFinite(to) || from < 0 || to <= from) {
    return false;
  }

  view.dispatch({
    selection: { anchor: from },
    scrollIntoView: true,
  });

  return true;
}

export default function markdownLivePlugin(config) {
  const mergedConfig = {
    ...(config.lezer ?? {}),
    base: config.lezer?.base ?? markdownLanguage,
    extensions: [tagParser, ...(config.lezer?.extensions ?? [])],
  };

  return ViewPlugin.fromClass(RichEditPlugin, {
    decorations: (view) => view.decorations,
    provide: () => [
      metadataLiveDecorations(config.metadata),
      taskCheckboxPlugin,
      highlightDecorations,
      inlineCodeDecorations,
      structuralLineDecorations,
      inlineHtmlDecorations,
      liveLinkDecorations,
      renderBlock(config.markdoc),
      syntaxHighlighting(highlightStyle),
      markdown(mergedConfig),
    ],
    eventHandlers: {
      mousedown(event, view) {
        if (event.button === 0 && toggleRenderedBlockTaskCheckbox(view, event.target)) {
          event.preventDefault();
          return true;
        }

        if (event.button === 1) {
          const link = resolveEditorLink(view, event);
          if (link) {
            event.preventDefault();
            return true;
          }
        }

        if (event.button === 0) {
          const link = resolveEditorLink(view, event);
          if (link) {
            event.preventDefault();
            void config.onOpenLink?.(link);
            return true;
          }
        }

        if (event.button === 0 && focusInlineHtmlSource(view, event.target)) {
          event.preventDefault();
          return true;
        }

        const targetElement = event.target instanceof Element ? event.target : null;
        if (event.button === 0 && targetElement?.matches(".cm-markdoc-renderBlock, .cm-markdoc-renderBlock *")) {
          try {
            view.dispatch({ selection: { anchor: view.posAtDOM(targetElement) } });
          } catch {
            return false;
          }
        }

        return false;
      },
      auxclick(event, view) {
        if (event.button !== 1) {
          return false;
        }

        const link = resolveEditorLink(view, event);
        if (!link) {
          return false;
        }

        event.preventDefault();
        void config.onOpenLink?.({
          ...link,
          openInNewTab: true,
        });
        return true;
      },
    },
  });
}
