import { Decoration } from "@codemirror/view";
import { syntaxTree } from "@codemirror/language";

const tokenElement = [
  "InlineCode",
  "Emphasis",
  "StrongEmphasis",
  "Strikethrough",
  "FencedCode",
  "Link",
];

const tokenHidden = [
  "HardBreak",
  "LinkMark",
  "EmphasisMark",
  "StrikethroughMark",
  "CodeMark",
  "CodeInfo",
  "URL",
];

const decorationHidden = Decoration.mark({ class: "cm-markdoc-hidden" });
const decorationBullet = Decoration.mark({ class: "cm-markdoc-listMark cm-markdoc-listMark--bullet cm-markdoc-bullet" });
const decorationOrderedListMark = Decoration.mark({ class: "cm-markdoc-listMark cm-markdoc-listMark--ordered" });
const decorationCode = Decoration.mark({ class: "cm-markdoc-code" });
const decorationTag = Decoration.mark({ class: "cm-markdoc-tag" });
const decorationUnsupportedLink = Decoration.mark({ class: "cm-markdown-unsupportedLink" });

function collectWikiRanges(text, lineFrom) {
  const supported = [];
  const unsupported = [];
  const pattern = /\[\[([^\]\r\n]+)\]\]/g;
  let match = pattern.exec(text);

  while (match) {
    const from = lineFrom + match.index;
    const to = from + match[0].length;

    if (match[1].includes("|")) {
      unsupported.push({ from, to });
    } else {
      supported.push({ from, to });
    }

    match = pattern.exec(text);
  }

  return { supported, unsupported };
}

function isRangeWithinRanges(from, to, ranges) {
  return ranges.some((range) => from >= range.from && to <= range.to);
}

function collectUnsupportedReferenceLinkRanges(view, from, to) {
  const ranges = [];
  const text = view.state.doc.toString();

  syntaxTree(view.state).iterate({
    from,
    to,
    enter(node) {
      if (node.name !== "Link") {
        return undefined;
      }

      const raw = text.slice(node.from, node.to);
      const wrappedAsWiki = text[node.from - 1] === "[" && text[node.to] === "]";
      const markdownInlineLink = raw.includes("](") && raw.endsWith(")");

      if (!wrappedAsWiki && !markdownInlineLink && /^\[[^\]\r\n]+\]$/.test(raw)) {
        ranges.push({ from: node.from, to: node.to });
      }

      return undefined;
    },
  });

  return ranges;
}

export default class RichEditPlugin {
  constructor(view) {
    this.decorations = this.process(view);
  }

  update(update) {
    if (update.docChanged || update.viewportChanged || update.selectionSet) {
      this.decorations = this.process(update.view);
    }
  }

  process(view) {
    const widgets = [];
    const [cursor] = view.state.selection.ranges;

    for (const { from, to } of view.visibleRanges) {
      const unsupportedWikiRanges = [];
      const unsupportedReferenceLinkRanges = collectUnsupportedReferenceLinkRanges(view, from, to);
      let lineNumber = view.state.doc.lineAt(from).number;
      const lastLineNumber = view.state.doc.lineAt(to).number;

      while (lineNumber <= lastLineNumber) {
        const line = view.state.doc.line(lineNumber);
        const ranges = collectWikiRanges(line.text, line.from);
        unsupportedWikiRanges.push(...ranges.unsupported);
        lineNumber += 1;
      }

      syntaxTree(view.state).iterate({
        from,
        to,
        enter(node) {
          if (node.name === "MarkdocTag") {
            widgets.push(decorationTag.range(node.from, node.to));
          }

          if (node.name === "FencedCode") {
            widgets.push(decorationCode.range(node.from, node.to));
          }

          if (node.name === "Link" && isRangeWithinRanges(node.from, node.to, unsupportedReferenceLinkRanges)) {
            widgets.push(decorationUnsupportedLink.range(node.from, node.to));
          }

          if (
            (node.name.startsWith("ATXHeading") || tokenElement.includes(node.name)) &&
            cursor.from >= node.from && cursor.to <= node.to
          ) {
            return false;
          }

          if (
            node.name === "ListMark" &&
            node.matchContext(["BulletList", "ListItem"]) &&
            cursor.from !== node.from &&
            cursor.from !== node.from + 1
          ) {
            widgets.push(decorationBullet.range(node.from, node.to));
          }

          if (
            node.name === "ListMark" &&
            node.matchContext(["OrderedList", "ListItem"]) &&
            cursor.from !== node.from &&
            cursor.from !== node.from + 1
          ) {
            widgets.push(decorationOrderedListMark.range(node.from, node.to));
          }

          if (node.name === "HeaderMark") {
            widgets.push(decorationHidden.range(node.from, node.to + 1));
          }

          if (tokenHidden.includes(node.name)) {
            if (
              isRangeWithinRanges(node.from, node.to, unsupportedWikiRanges) ||
              isRangeWithinRanges(node.from, node.to, unsupportedReferenceLinkRanges)
            ) {
              return undefined;
            }

            widgets.push(decorationHidden.range(node.from, node.to));
          }

          return undefined;
        },
      });
    }

    return Decoration.set(widgets);
  }
}
