import { RangeSet, StateField } from "@codemirror/state";
import { Decoration, EditorView } from "@codemirror/view";
import { syntaxTree } from "@codemirror/language";

const highlightContentDecoration = Decoration.mark({ class: "cm-markdown-highlight" });
const hiddenMarkerDecoration = Decoration.mark({ class: "cm-markdoc-hidden" });
const highlightPattern = /==([^=\r\n][^=\r\n]*?)==/g;

function selectionTouchesRange(selection, from, to) {
  return selection.ranges.some((range) => range.from <= to && range.to >= from);
}

function buildHighlightDecorations(state) {
  const decorations = [];

  syntaxTree(state).iterate({
    enter(node) {
      if (!["Paragraph", "ATXHeading1", "ATXHeading2", "ATXHeading3", "ATXHeading4", "SetextHeading1", "SetextHeading2"].includes(node.name)) {
        return undefined;
      }

      const text = state.doc.sliceString(node.from, node.to);
      let match = highlightPattern.exec(text);

      while (match) {
        const from = node.from + match.index;
        const to = from + match[0].length;

        if (!selectionTouchesRange(state.selection, from, to)) {
          decorations.push(hiddenMarkerDecoration.range(from, from + 2));
          decorations.push(highlightContentDecoration.range(from + 2, to - 2));
          decorations.push(hiddenMarkerDecoration.range(to - 2, to));
        }

        match = highlightPattern.exec(text);
      }

      return undefined;
    },
  });

  return RangeSet.of(decorations, true);
}

export default StateField.define({
  create(state) {
    return buildHighlightDecorations(state);
  },

  update(_decorations, transaction) {
    return buildHighlightDecorations(transaction.state);
  },

  provide(field) {
    return EditorView.decorations.from(field);
  },
});
