import { Decoration, ViewPlugin, WidgetType } from "@codemirror/view";
import { syntaxTree } from "@codemirror/language";

const VOID_HTML_TAGS = new Set([
  "area",
  "base",
  "br",
  "col",
  "embed",
  "hr",
  "img",
  "input",
  "link",
  "meta",
  "param",
  "source",
  "track",
  "wbr",
]);

const BLOCKED_INLINE_HTML_TAGS = new Set([
  "address",
  "article",
  "aside",
  "blockquote",
  "body",
  "canvas",
  "details",
  "dialog",
  "div",
  "dl",
  "fieldset",
  "figcaption",
  "figure",
  "footer",
  "form",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "header",
  "hr",
  "iframe",
  "li",
  "main",
  "nav",
  "ol",
  "p",
  "pre",
  "section",
  "summary",
  "table",
  "tbody",
  "td",
  "tfoot",
  "th",
  "thead",
  "tr",
  "ul",
  "video",
]);

const htmlTagPattern = /^<\s*(\/)?\s*([A-Za-z][\w:-]*)\b[^>]*?(\/)?\s*>$/;

class InlineHtmlWidget extends WidgetType {
  constructor({ source, rendered, from, to }) {
    super();
    this.source = source;
    this.rendered = rendered;
    this.from = from;
    this.to = to;
  }

  eq(other) {
    return (
      other.source === this.source &&
      other.rendered === this.rendered &&
      other.from === this.from &&
      other.to === this.to
    );
  }

  updateDOM(dom) {
    if (!(dom instanceof HTMLElement)) {
      return false;
    }

    dom.innerHTML = this.rendered;
    dom.dataset.sourceFrom = String(this.from);
    dom.dataset.sourceTo = String(this.to);
    return true;
  }

  toDOM() {
    const element = document.createElement("span");
    element.className = "cm-markdoc-renderInlineHtml";
    element.setAttribute("contenteditable", "false");
    element.dataset.sourceFrom = String(this.from);
    element.dataset.sourceTo = String(this.to);
    element.innerHTML = this.rendered;
    return element;
  }

  ignoreEvent() {
    return false;
  }
}

function parseHtmlTag(text) {
  const source = String(text || "").trim();
  if (!source || /^<\s*![^>]*>$/i.test(source) || /^<\s*\?[^>]*>$/i.test(source)) {
    return null;
  }

  const match = source.match(htmlTagPattern);
  if (!match) {
    return null;
  }

  const tagName = String(match[2] || "").toLowerCase();
  return {
    tagName,
    isClosing: Boolean(match[1]),
    isSelfClosing: Boolean(match[3]) || VOID_HTML_TAGS.has(tagName),
  };
}

function selectionTouchesRange(selection, from, to) {
  return selection.ranges.some((range) => {
    if (range.empty) {
      return range.from >= from && range.from < to;
    }

    return range.from < to && range.to > from;
  });
}

function isInlineHtmlRenderable(source) {
  const html = String(source || "");
  if (!html || html.includes("\n")) {
    return false;
  }

  const template = document.createElement("template");
  template.innerHTML = html;

  if (!template.content.firstChild) {
    return false;
  }

  return !Array.from(template.content.querySelectorAll("*")).some((element) =>
    BLOCKED_INLINE_HTML_TAGS.has(element.tagName.toLowerCase()),
  );
}

function buildInlineHtmlWidget(source) {
  return [
    "<span class=\"markdown-engine-richContent markdown-engine-inlineHtmlContent\">",
    source,
    "</span>",
  ].join("");
}

function collectInlineHtmlRanges(view) {
  const ranges = [];
  const seen = new Set();

  for (const { from, to } of view.visibleRanges) {
    const tags = [];
    syntaxTree(view.state).iterate({
      from,
      to,
      enter(node) {
        if (node.name !== "HTMLTag") {
          return undefined;
        }

        const key = `${node.from}:${node.to}`;
        if (seen.has(key)) {
          return undefined;
        }

        seen.add(key);
        tags.push({
          from: node.from,
          to: node.to,
          text: view.state.doc.sliceString(node.from, node.to),
        });
        return undefined;
      },
    });

    tags.sort((left, right) => left.from - right.from);
    const stack = [];

    for (const tag of tags) {
      const parsed = parseHtmlTag(tag.text);
      if (!parsed) {
        continue;
      }

      if (parsed.isSelfClosing) {
        if (stack.length === 0) {
          ranges.push({
            from: tag.from,
            to: tag.to,
          });
        }
        continue;
      }

      if (!parsed.isClosing) {
        stack.push({
          from: tag.from,
          tagName: parsed.tagName,
          depth: stack.length,
        });
        continue;
      }

      const openIndex = stack.findLastIndex((entry) => entry.tagName === parsed.tagName);
      if (openIndex < 0) {
        continue;
      }

      const openingTag = stack[openIndex];
      stack.length = openIndex;

      if (openingTag.depth === 0) {
        ranges.push({
          from: openingTag.from,
          to: tag.to,
        });
      }
    }
  }

  return ranges;
}

function buildDecorations(view) {
  const decorations = [];
  const ranges = collectInlineHtmlRanges(view);

  for (const range of ranges) {
    if (selectionTouchesRange(view.state.selection, range.from, range.to)) {
      continue;
    }

    const source = view.state.doc.sliceString(range.from, range.to);
    if (!isInlineHtmlRenderable(source)) {
      continue;
    }

    decorations.push(
      Decoration.replace({
        widget: new InlineHtmlWidget({
          source,
          rendered: buildInlineHtmlWidget(source),
          from: range.from,
          to: range.to,
        }),
      }).range(range.from, range.to),
    );
  }

  return Decoration.set(decorations, true);
}

export default ViewPlugin.fromClass(class {
  constructor(view) {
    this.decorations = buildDecorations(view);
  }

  update(update) {
    if (update.docChanged || update.viewportChanged || update.selectionSet) {
      this.decorations = buildDecorations(update.view);
    }
  }
}, {
  decorations: (instance) => instance.decorations,
});
