import { Decoration, EditorView, ViewPlugin, WidgetType } from "@codemirror/view";

const taskLinePattern = /^(\s*[-*+]\s+)\[([ xX])\](\s+)/;

class TaskCheckboxWidget extends WidgetType {
  constructor(checked) {
    super();
    this.checked = checked;
  }

  eq(other) {
    return other.checked === this.checked;
  }

  toDOM() {
    const wrap = document.createElement("span");
    wrap.className = "cm-task-checkboxWidget";
    wrap.setAttribute("aria-hidden", "true");
    wrap.setAttribute("data-checked", this.checked ? "true" : "false");

    // CodeMirror's decoration example wraps the input to avoid
    // contenteditable/browser quirks around raw checkboxes.
    const input = wrap.appendChild(document.createElement("input"));
    input.className = "cm-task-checkboxWidgetInput";
    input.type = "checkbox";
    input.checked = this.checked;
    input.tabIndex = -1;

    const box = wrap.appendChild(document.createElement("span"));
    box.className = "cm-task-checkboxWidgetBox";

    return wrap;
  }

  ignoreEvent() {
    return false;
  }
}

function isSelectionInside(selection, from, to) {
  return selection.ranges.some((range) => range.from <= to && range.to >= from);
}

function buildTaskCheckboxes(view) {
  const widgets = [];
  const seenLines = new Set();

  for (const { from, to } of view.visibleRanges) {
    let line = view.state.doc.lineAt(from);

    while (line.from <= to) {
      if (!seenLines.has(line.from)) {
        seenLines.add(line.from);

        const match = line.text.match(taskLinePattern);
        if (match) {
          const markerFrom = line.from + match[1].length;
          const markerTo = markerFrom + 3;

          if (!isSelectionInside(view.state.selection, markerFrom, markerTo)) {
            widgets.push(
              Decoration.replace({
                widget: new TaskCheckboxWidget(match[2].toLowerCase() === "x"),
              }).range(markerFrom, markerTo),
            );
          }
        }
      }

      if (line.to >= to) {
        break;
      }

      line = view.state.doc.line(line.number + 1);
    }
  }

  return Decoration.set(widgets, true);
}

function toggleTaskCheckbox(view, target) {
  const widget = target instanceof Element ? target.closest(".cm-task-checkboxWidget") : null;
  if (!(widget instanceof HTMLElement)) {
    return false;
  }

  const input = widget.querySelector(".cm-task-checkboxWidgetInput");
  if (!(input instanceof HTMLInputElement)) {
    return false;
  }

  const pos = view.posAtDOM(widget);
  const line = view.state.doc.lineAt(pos);
  const match = line.text.match(taskLinePattern);

  if (!match) {
    return false;
  }

  const markerFrom = line.from + match[1].length;

  view.dispatch({
    changes: {
      from: markerFrom,
      to: markerFrom + 3,
      insert: input.checked ? "[ ]" : "[x]",
    },
  });

  return true;
}

export default ViewPlugin.fromClass(class {
  constructor(view) {
    this.decorations = buildTaskCheckboxes(view);
  }

  update(update) {
    if (update.docChanged || update.viewportChanged || update.selectionSet) {
      this.decorations = buildTaskCheckboxes(update.view);
    }
  }
}, {
  decorations: (instance) => instance.decorations,
  eventHandlers: {
    mousedown(event, view) {
      if (toggleTaskCheckbox(view, event.target)) {
        return true;
      }

      return false;
    },
  },
});
