import markdoc from "@markdoc/markdoc";
import { renderMarkdown } from "./markdownRenderer.js";

const MARKDOWN_BLOCK_DEFINITIONS = {
  Blockquote: { kind: "blockquote" },
  Table: { kind: "table" },
  HTMLBlock: { kind: "html-block" },
};

function wrapRichContent(html, kind) {
  const normalizedHtml = String(html || "").trim();

  return [
    `<article class="markdown-engine-richContent markdown-engine-liveWidgetContent" data-block-kind="${kind}">`,
    normalizedHtml,
    "</article>",
  ].join("");
}

function renderMarkdocBlock(source, config) {
  const documentNode = markdoc.parse(source);
  const transformed = markdoc.transform(documentNode, config);
  return markdoc.renderers.html(transformed);
}

export function getBlockRenderDefinition(nodeName) {
  if (nodeName === "MarkdocTag") {
    return {
      kind: "markdoc-tag",
      render(source, config) {
        return wrapRichContent(renderMarkdocBlock(source, config), "markdoc-tag");
      },
    };
  }

  const definition = MARKDOWN_BLOCK_DEFINITIONS[nodeName];
  if (!definition) {
    return null;
  }

  return {
    kind: definition.kind,
    render(source) {
      return wrapRichContent(renderMarkdown(source), definition.kind);
    },
  };
}
