import React, { useEffect, useMemo, useRef, useState } from "react";
import { defaultKeymap, history, historyKeymap, indentWithTab } from "@codemirror/commands";
import { indentOnInput } from "@codemirror/language";
import { languages } from "@codemirror/language-data";
import { EditorState } from "@codemirror/state";
import { EditorView, highlightActiveLine, keymap, rectangularSelection } from "@codemirror/view";
import markdocConfig from "./markdocConfig.js";
import markdownLivePlugin from "./markdownLivePlugin.js";
import { setMetadataCollapsedEffect } from "./metadataLiveDecorations.js";
import { extractMarkdownMetadata, formatMarkdownMetadataSummary } from "./metadata.js";
import { renderMarkdown } from "./markdownRenderer.js";

const fs = window.require("fs");

export function readEmbeddedMarkdownFile(filePath) {
  if (!filePath) {
    return "";
  }

  try {
    return fs.readFileSync(filePath, "utf8");
  } catch {
    return "";
  }
}

export function EmbeddedMarkdownReadSurface({
  filePath = "",
  value = "",
  compact = false,
  metadataCollapsed: metadataCollapsedProp = undefined,
  onMetadataCollapsedChange = null,
  defaultMetadataCollapsed = true,
}) {
  const source = useMemo(
    () => (typeof value === "string" && value.length ? value : readEmbeddedMarkdownFile(filePath)),
    [filePath, value],
  );
  const {
    metadata,
    body,
  } = useMemo(() => extractMarkdownMetadata(source), [source]);
  const html = useMemo(() => renderMarkdown(body), [body]);
  const [metadataCollapsedState, setMetadataCollapsedState] = useState(Boolean(defaultMetadataCollapsed));
  const metadataSummary = useMemo(
    () => formatMarkdownMetadataSummary(metadata.length),
    [metadata.length],
  );
  const isMetadataCollapsed = metadataCollapsedProp == null
    ? metadataCollapsedState
    : Boolean(metadataCollapsedProp);

  useEffect(() => {
    if (metadataCollapsedProp == null) {
      setMetadataCollapsedState(Boolean(defaultMetadataCollapsed));
    }
  }, [defaultMetadataCollapsed, filePath, metadataCollapsedProp]);

  const handleMetadataToggle = () => {
    const nextValue = !isMetadataCollapsed;
    if (metadataCollapsedProp == null) {
      setMetadataCollapsedState(nextValue);
    }
    onMetadataCollapsedChange?.(nextValue);
  };

  return (
    <div className={["markdown-engine-read", compact ? "markdown-engine-read--compact" : ""].filter(Boolean).join(" ")}>
      <div className="markdown-engine-document">
        {metadata.length ? (
          <section
            className={[
              "markdown-engine-metadata",
              isMetadataCollapsed ? "is-collapsed" : "is-expanded",
            ].join(" ")}
            aria-label="Propiedades"
          >
            <button
              type="button"
              className={[
                "markdown-engine-metadataToggleButton",
                isMetadataCollapsed ? "is-collapsed" : "is-expanded",
              ].join(" ")}
              onClick={handleMetadataToggle}
              aria-expanded={!isMetadataCollapsed}
            >
              <span className="markdown-engine-metadataToggleMain">
                <span className="markdown-engine-metadataDisclosure" aria-hidden="true" />
                <span className="markdown-engine-metadataLabel">Propiedades</span>
              </span>
              {metadataSummary ? (
                <span className="markdown-engine-metadataSummary">{metadataSummary}</span>
              ) : null}
            </button>

            {!isMetadataCollapsed ? (
              <div className="markdown-engine-metadataBody">
                {metadata.map((entry) => (
                  <div key={`${entry.key}:${entry.value}`} className="markdown-engine-metadataRow">
                    <span className="markdown-engine-metadataKey">{entry.key}</span>
                    <span className="markdown-engine-metadataValue">{entry.value}</span>
                  </div>
                ))}
              </div>
            ) : null}
          </section>
        ) : null}

        <article className="markdown-engine-richContent" dangerouslySetInnerHTML={{ __html: html }} />
      </div>
    </div>
  );
}

export function EmbeddedMarkdownLiveEditor({
  filePath = "",
  value = "",
  onChange = () => {},
  metadataCollapsed = true,
  onMetadataCollapsedChange = null,
  persistToDisk = undefined,
}) {
  const mountRef = useRef(null);
  const viewRef = useRef(null);
  const initialValueRef = useRef(value);
  const onChangeRef = useRef(onChange);
  const shouldPersistToDisk = persistToDisk == null
    ? Boolean(filePath)
    : Boolean(persistToDisk && filePath);

  useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);

  useEffect(() => {
    if (!mountRef.current) {
      return undefined;
    }

    let saveTimeout = null;
    const updateListener = EditorView.updateListener.of((update) => {
      if (!update.docChanged) {
        return;
      }

      if (saveTimeout) {
        window.clearTimeout(saveTimeout);
      }

      saveTimeout = window.setTimeout(() => {
        const nextValue = update.state.doc.toString();
        if (shouldPersistToDisk && filePath) {
          fs.writeFileSync(filePath, nextValue, "utf8");
        }
        onChangeRef.current(nextValue);
      }, 500);
    });

    const state = EditorState.create({
      doc: initialValueRef.current,
      extensions: [
        markdownLivePlugin({
          markdoc: markdocConfig,
          metadata: {
            defaultCollapsed: metadataCollapsed,
            onCollapsedChange: onMetadataCollapsedChange,
          },
          lezer: {
            codeLanguages: languages,
          },
          onOpenLink: () => ({ ok: false, error: "Link navigation disabled in embedded markdown surface." }),
        }),
        updateListener,
        EditorView.lineWrapping,
        history(),
        rectangularSelection(),
        highlightActiveLine(),
        indentOnInput(),
        keymap.of([indentWithTab, ...defaultKeymap, ...historyKeymap]),
      ],
    });

    const view = new EditorView({
      state,
      parent: mountRef.current,
    });
    viewRef.current = view;

    return () => {
      if (saveTimeout) {
        window.clearTimeout(saveTimeout);
      }
      viewRef.current = null;
      view.destroy();
    };
  }, [filePath, metadataCollapsed, onMetadataCollapsedChange, shouldPersistToDisk]);

  useEffect(() => {
    if (!viewRef.current) {
      return;
    }

    viewRef.current.dispatch({
      effects: setMetadataCollapsedEffect.of(Boolean(metadataCollapsed)),
    });
  }, [metadataCollapsed]);

  return <div className="markdown-engine-liveEditor" ref={mountRef} />;
}
