import { RangeSet, StateField } from "@codemirror/state";
import { syntaxTree } from "@codemirror/language";
import { Decoration, EditorView } from "@codemirror/view";

const EXTERNAL_TARGET_PATTERN = /^[a-z][a-z0-9+.-]*:/i;
const markdownLiveLinkDecoration = Decoration.mark({
  class: "cm-markdown-liveLink",
  attributes: {
    "data-nexus-live-link": "true",
    "data-nexus-live-link-kind": "markdown",
  },
});
const wikiLiveLinkDecoration = Decoration.mark({
  class: "cm-markdown-liveLink cm-markdown-liveLink--wiki",
  attributes: {
    "data-nexus-live-link": "true",
    "data-nexus-live-link-kind": "wiki",
  },
});
const wikiEditingLiveLinkDecoration = Decoration.mark({
  class: "cm-markdown-liveLink cm-markdown-liveLink--wiki cm-markdown-liveLink--editing",
  attributes: {
    "data-nexus-live-link": "true",
    "data-nexus-live-link-kind": "wiki",
  },
});

function normalizeWikiLinkTarget(value) {
  const raw = String(value || "").trim();
  if (!raw || raw.includes("|")) {
    return null;
  }

  return raw;
}

function isInternalTarget(target) {
  const normalized = String(target || "").trim();
  if (!normalized) {
    return false;
  }

  return !EXTERNAL_TARGET_PATTERN.test(normalized) && !normalized.startsWith("#");
}

function getMarkdownLinkTarget(state, linkNode) {
  const raw = state.doc.sliceString(linkNode.from, linkNode.to).trim();
  if (!raw || raw.startsWith("![")) {
    return null;
  }

  const separatorIndex = raw.lastIndexOf("](");
  if (separatorIndex < 0 || !raw.endsWith(")")) {
    return null;
  }

  const target = raw.slice(separatorIndex + 2, -1).trim();
  return isInternalTarget(target) ? target : null;
}

function selectionTouchesRange(selection, from, to) {
  return selection.ranges.some((range) => range.from <= to && range.to >= from);
}

function collectWikiLinkDecorations(state, decorations) {
  const pattern = /\[\[([^\]\r\n]+)\]\]/g;

  for (let lineNumber = 1; lineNumber <= state.doc.lines; lineNumber += 1) {
    const line = state.doc.line(lineNumber);
    let match = pattern.exec(line.text);

    while (match) {
      const target = normalizeWikiLinkTarget(match[1]);
      if (target && isInternalTarget(target)) {
        const from = line.from + match.index;
        const to = from + match[0].length;
        const decoration = selectionTouchesRange(state.selection, from, to)
          ? wikiEditingLiveLinkDecoration
          : wikiLiveLinkDecoration;
        decorations.push(decoration.range(from, to));
      }

      match = pattern.exec(line.text);
    }
  }
}

function buildDecorations(state) {
  const decorations = [];

  syntaxTree(state).iterate({
    enter(node) {
      if (node.name !== "Link") {
        return undefined;
      }

      if (getMarkdownLinkTarget(state, node)) {
        decorations.push(markdownLiveLinkDecoration.range(node.from, node.to));
      }

      return undefined;
    },
  });

  collectWikiLinkDecorations(state, decorations);
  return RangeSet.of(decorations, true);
}

export default StateField.define({
  create(state) {
    return buildDecorations(state);
  },

  update(_decorations, transaction) {
    return buildDecorations(transaction.state);
  },

  provide(field) {
    return EditorView.decorations.from(field);
  },
});
